import { useState, useEffect } from 'react';

function useDonnees(initialData = [], fetchFunction = null) {
  const [donnees, setDonnees] = useState(initialData);
  const [loading, setLoading] = useState(fetchFunction ? true : false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (fetchFunction) {
      const fetchData = async () => {
        try {
          setLoading(true);
          const data = await fetchFunction();
          setDonnees(data);
          setError(null);
        } catch (err) {
          setError('Erreur lors du chargement des données');
          console.error('Erreur:', err);
        } finally {
          setLoading(false);
        }
      };

      fetchData();
    }
  }, [fetchFunction]);

  const ajouterElement = async (element, createFunction = null) => {
    try {
      if (createFunction) {
        const nouveauElement = await createFunction(element);
        setDonnees([...donnees, nouveauElement]);
        return nouveauElement;
      } else {
        setDonnees([...donnees, element]);
        return element;
      }
    } catch (err) {
      setError("Erreur lors de l'ajout");
      throw err;
    }
  };

  const modifierElement = async (id, idField, nouvellesDonnees, updateFunction = null) => {
    try {
      if (updateFunction) {
        const elementMisAJour = await updateFunction(id, nouvellesDonnees);
        setDonnees(donnees.map(item => 
          item[idField] === id ? elementMisAJour : item
        ));
        return elementMisAJour;
      } else {
        setDonnees(donnees.map(item => 
          item[idField] === id ? { ...item, ...nouvellesDonnees } : item
        ));
        return nouvellesDonnees;
      }
    } catch (err) {
      setError("Erreur lors de la modification");
      throw err;
    }
  };

  const supprimerElement = async (id, idField, deleteFunction = null) => {
    try {
      if (deleteFunction) {
        await deleteFunction(id);
        setDonnees(donnees.filter(item => item[idField] !== id));
      } else {
        setDonnees(donnees.filter(item => item[idField] !== id));
      }
    } catch (err) {
      setError("Erreur lors de la suppression");
      throw err;
    }
  };

  return {
    donnees,
    setDonnees,
    loading,
    error,
    setError,
    ajouterElement,
    modifierElement,
    supprimerElement
  };
}

export default useDonnees;
